def parse_date(raw: str) -> date:
    """Borough writes an ISO date, ``YYYY-MM-DD``."""
    try:
        return date.fromisoformat(raw.strip())
    except ValueError as exc:
        raise LedgerParseError(f"Borough date {raw!r} is not an ISO date") from exc


def parse_amount(raw: str) -> Decimal:
    """Borough amounts are integer cents; see :func:`to_major_units`."""
    return to_major_units(raw)


def to_record(row: dict[str, str], unknown_label: str) -> Record:
    """Turn one raw Borough row into a normalized :class:`~ledgerkit.core.records.Record`."""
    code = row[ACCOUNT_FIELD].strip()
    return Record(
        record_id=row["doc_no"],
        source_system="B",
        date=parse_date(row[DATE_FIELD]),
        account_code=code,
        account_name=account_name(code, unknown_label),
        description=row["descr"],
        amount=parse_amount(row[AMOUNT_FIELD]),
    )


